package holdout
import "testing"
func TestAccumulator(t *testing.T) {
    w:=Accumulator{Horizon:5}
    for _,tc:=range []struct{at,value,want int}{{0,3,3},{4,2,5},{5,7,9},{5,-2,7},{10,1,1}} {
        got,ok:=w.Observe(tc.at,tc.value); if !ok || got!=tc.want { t.Fatalf("at %d aggregate %d",tc.at,got) }
    }
    if _,ok:=w.Observe(9,100);ok { t.Fatal("backdated reading accepted") }
    if got,ok:=w.Observe(10,2);!ok || got!=3 { t.Fatal(got,ok) }
}

